def scale(values, factor):
    if factor == 0:
        return []
    scaled = [v * factor for v in values]
    return scaled

def variance(xs):
    mean = sum(xs) / len(xs)
    if len(xs) < 2:
        return 0.0
    return sum((x - mean) ** 2 for x in xs) / (len(xs) - 1)

